import{_ as n,l as r,o as i,c as s,v as e,p as l,x as t,d as p,i as c,S as _}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"列昂惕夫技术","description":"","frontmatter":{"title":"列昂惕夫技术","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/leontief-technology.md","filePath":"econ/leontief-technology.md","lastUpdated":1789023840000}'),d={name:"econ/leontief-technology.md"};function h(m,a,E,f,A,u){const o=r("Mermaid");return i(),s("div",null,[a[1]||(a[1]=e('<h1 id="列昂惕夫技术" tabindex="-1">列昂惕夫技术 <a class="header-anchor" href="#列昂惕夫技术" aria-label="Permalink to &quot;列昂惕夫技术&quot;">​</a></h1><div class="epigraph"><p>投入必须按固定配方走：少一种，其余再多也变不成产出；等产量是直角，替代弹性为零。</p><footer>—— 据 Leontief, The Structure of American Economy, 1919–1939, 1941；对照 Hicks 的 $\\sigma$ 极点整理</footer></div><p><a href="/econ/elasticity-of-substitution">上一课</a>（替代弹性）。把 \\(\\sigma\\) 写成等产量弯曲，并点名 \\(\\sigma\\to 0\\) 是 CES 的列昂惕夫极限。本课不重写 Hicks 的对数导数，也不把一次齐次再证一遍。缺口是这个极点本身：固定比例技术长什么样，有效投入怎样决定 \\(q\\)，后课成本最小化在折拐处会碰到什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>配方 \\((a_1,\\ldots,a_n)\\gg 0\\)。可行产出</p> \\[q\\le f(z)=\\min_i\\frac{z_i}{a_i}. \\]<p>要生产 \\(q\\)，每种要素至少 \\(a_i q\\)。多出来的投入是浪费——<a href="/econ/free-disposal-inada">自由处置</a>允许，但有效计划不会留。等产量是直角：只在角点 \\(z=aq\\) 上两种要素同时卡紧；沿一条边，一种要素多余，TRS 是 \\(0\\) 或 \\(\\infty\\)，中间没有光滑切线。缺口不是再定义一次 \\(\\sigma\\)，而是：<strong>\\(\\sigma=0\\) 时「替代」这句话空了，后课的切条件 TRS \\(=w\\) 比没有内点可切。</strong></p><p>投入产出表把部门间的 \\(a_{ij}\\) 排成矩阵，列昂惕夫逆给出「最终需求一单位要多少总产出」。那是同一配方在多部门上的展开；本课先钉单产出 \\(f\\)。</p><h3 id="直角不是不可分" tabindex="-1">直角不是不可分 <a class="header-anchor" href="#直角不是不可分" aria-label="Permalink to &quot;直角不是不可分&quot;">​</a></h3><p>不可分是 \\(z\\) 不能连续调。列昂惕夫可以连续放大配方，\\(f\\) 一次齐次，欧拉分尽在有效射线 \\(z=aq\\) 上仍可读——只是边际产出是单侧的：卡紧要素的边际为正，多余要素的边际为零。不要把直角等产量写成整数机器。</p><p><span class="marginnote">CES 里 \\(\\rho\\to-\\infty\\) 时，\\((\\sum a_i z_i^{\\rho})^{1/\\rho}\\) 一致收敛到 \\(\\min_i z_i/a_i\\)。\\(\\sigma=0\\) 不是另一种技术家族，是弯曲参数的边界值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有效计划必在角上：\\(z_i=a_i q\\) 对所有 \\(i\\)。成本一旦有 \\(w\\)，最小成本直接是 \\(c(w,q)=q\\,w\\cdot a\\)，条件需求钉死在配方上，对 \\(w\\) 无反应——这正是 \\(\\sigma=0\\) 的对偶面。本课仍不解规划，只把几何交给下一课：支撑超平面可以是一整族，只要 \\(w\\ge 0\\)，角点都被支撑。</p><p>投入产出：中间品按 \\(A\\) 消耗，\\((I-A)^{-1}\\) 存在当谱半径小于一（霍金斯–西蒙）。那是一般均衡生产课的多部门语言；这里只需知道「固定配方」可以从一个 \\(f\\) 长成一张表。</p>',14)),(i(),l(_,null,{default:t(()=>[c(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%CF%83%20%E5%BA%A6%E9%87%8F%E5%BC%AF%E6%9B%B2%22%5D%20--%3E%20ZERO%5B%22%CF%83%20%3D%200%EF%BC%9A%E7%9B%B4%E8%A7%92%E7%AD%89%E4%BA%A7%E9%87%8F%22%5D%0A%20%20ZERO%20--%3E%20MIN%5B%22f%20%3D%20min_i%20z_i%20%2F%20a_i%22%5D%0A%20%20ZERO%20--%3E%20CORNER%5B%22%E6%9C%89%E6%95%88%E7%82%B9%E5%8F%AA%E5%9C%A8%E8%A7%92%E4%B8%8A%22%5D%0A%20%20CORNER%20--%3E%20COST%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9Ac%20%3D%20q%20w%C2%B7a%EF%BC%8C%E5%88%87%E6%9D%A1%E4%BB%B6%E5%8F%98%E6%94%AF%E6%92%91%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>不要把 \\(a_i\\) 写成偏好参数。配方是物质定额，不是 \\(u\\) 的互补。消费者 Leontief 偏好是对偶故事，本课是技术。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么 \\(\\sigma=0\\)：沿等产量想用 \\(j\\) 换 \\(k\\)，立刻有一种要素松弛、产出掉下来——要维持 \\(q\\) 必须把另一种也按比例加回，投入比被锁死。对数导数的分子为零。</p><p>边际产出的机制是短边：\\(\\partial f/\\partial z_i\\) 在 \\(z_i\\gt a_i q\\) 时为零，在刚好卡紧时为 \\(1/a_i\\)（另一要素不松）。竞争按边际付酬时，多余要素得零，卡紧要素分尽——仍是<a href="/econ/homothetic-production">欧拉</a>，只是梯度换成超梯度。</p><p><span class="marginnote">列昂惕夫 1941 的表是经验构造，不是从 CES 取极限推出来的。教学上把 \\(\\sigma=0\\) 与投入产出配方当成同一几何的两种写法：一种强调等产量，一种强调部门定额。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>配方随 \\(q\\) 变（非线性列昂惕夫）时一次齐次丢掉，角点仍在，只是 \\(a(q)\\) 要重估。联合生产、副产品让「一种产出一个 min」不够，要回到集合 \\(Y\\)。短期某些要素固定，直角变成「短边更短」，那是沉没课的固定要素，不是本课改 \\(\\sigma\\)。</p><p>后课<a href="/econ/cost-minimization">成本最小化</a>在光滑点写 TRS \\(=w\\) 比；碰到本课的角，改成要素价格落在超微分里，条件需求可以对 \\(w\\) 一段不变。</p><p>后课默认：列昂惕夫是 \\(\\sigma=0\\) 的固定比例技术；有效投入在角上；成本对 \\(w\\) 的反应要等对偶课用支撑来写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(f=\\min_i z_i/a_i\\) 给出直角等产量，有效计划锁在配方射线上。</li><li>\\(\\sigma=0\\) 是弯曲的极点，不是不可分，也不是规模报酬的另一种说法。</li><li>无内点切线，后课成本最小化用支撑超平面，不靠 TRS 等式。</li><li>投入产出表是同一配方的多部门展开。</li><li>出处：Leontief, 1941；Hicks \\(\\sigma\\) 的 \\(\\rho\\to-\\infty\\) 极限见 Varian。</li></ul>',11))])}const q=n(d,[["render",h]]);export{B as __pageData,q as default};
